export const GERBER_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/gerber-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getGerberStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(GERBER_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
